const src=$('Check Missing Essentials').first().json;
const raw=$input.first()?.json??{};
let parsed=null,err='';

try{
  let content = raw.output ?? raw.text ?? raw.message?.content ?? '';

  // Agar AI ne direct object bheja hai
  if (typeof content === 'object') {
      parsed = content;
  } else {
      // Agar string bheja hai (Markdown etc. hata kar)
      const s = String(content).replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
      if(!s) throw Error('AI response empty');
      parsed = JSON.parse(s);
  }

  if(!parsed || typeof parsed!=='object' || Array.isArray(parsed)) throw Error('Root not object');
  if(!Array.isArray(parsed.assumptions)) parsed.assumptions=[];
  if(!Array.isArray(parsed.unresolved_requirements)) parsed.unresolved_requirements=[];
  if(!Array.isArray(parsed.limitations)) parsed.limitations=[];
}catch(e){
  err=String(e.message||e).slice(0,200);
  parsed=null;
}

let provider='none';
if(parsed!==null){
  let geminiOutput=null;
  try{const gem=$('Gemini AI Generator (Fallback)').first()?.json;if(gem&&(typeof gem.output==='string'||typeof gem.text==='string'))geminiOutput=gem;}catch(e){}
  let groqOutput=null;
  try{const grq=$('Groq AI Generator').first()?.json;if(grq&&(typeof grq.output==='string'||typeof grq.text==='string'))groqOutput=grq;}catch(e){}

  if(geminiOutput&&!groqOutput)provider='gemini';
  else if(groqOutput&&!geminiOutput)provider='groq';
  else if(geminiOutput&&groqOutput)provider='groq';
  else provider='groq';
}

return [{json:{...src,ai_valid:!!parsed,ai_error:err,ai_data:parsed,ai_provider:provider}}];

const x=$input.first().json;
const issues=[];
let w=null;

if(x.ai_valid && x.ai_data){
  w=x.ai_data.generated_workflow_json;
  if(!w || typeof w!=='object' || Array.isArray(w)){
    issues.push('generated_workflow_json must be object');
    w=null;
  }
}

if(w){
  if(typeof w.name!=='string'||!w.name.trim())issues.push('workflow.name must be non-empty string');

  const nodes = Array.isArray(w.nodes) ? w.nodes : [];
  if(!Array.isArray(w.nodes)) issues.push('workflow.nodes must be array');
  else if(w.nodes.length===0) issues.push('workflow.nodes must not be empty');

  if(!w.connections||typeof w.connections!=='object'||Array.isArray(w.connections))issues.push('workflow.connections must be object');

  const ids=new Set(), names=new Set();
  for(const n of nodes){
    if(!n||typeof n!=='object'){issues.push('node entry invalid');continue;}

    // AUTO FIX 1: Agar AI ne id nahi di hai, toh naya ID generate karo
    if(typeof n.id!=='string' || !n.id.trim()) {
        n.id = Math.random().toString(36).substring(2, 10); 
    }

    // AUTO FIX 2: Agar position nahi hai, toh default lagao
    if(!Array.isArray(n.position)||n.position.length!==2) {
        n.position = [0,0];
    }

    const label=n.name||n.id||'(unnamed)';

    if(ids.has(n.id))issues.push('node.id duplicate: '+n.id);
    else ids.add(n.id);

    if(typeof n.name!=='string'||!n.name.trim())issues.push('node.name missing: '+label);
    else if(names.has(n.name))issues.push('node.name duplicate: '+n.name);
    else names.add(n.name);

    if(typeof n.type!=='string'||!n.type.trim())issues.push('node.type missing: '+label);
    if(typeof n.typeVersion!=='number'||!isFinite(n.typeVersion)||n.typeVersion<0)issues.push('node.typeVersion invalid: '+label);
    if(!n.parameters||typeof n.parameters!=='object'||Array.isArray(n.parameters))issues.push('node.parameters invalid: '+label);
  }

  if(w.connections&&typeof w.connections==='object'){
    const nameSet=new Set(names);
    for(const [srcName,groups] of Object.entries(w.connections)){
      if(!nameSet.has(srcName))issues.push('connection source missing: '+srcName);
      if(!groups||typeof groups!=='object'||Array.isArray(groups)){issues.push('connection group invalid: '+srcName);continue;}
      for(const outs of Object.values(groups)){
        if(!Array.isArray(outs))continue;
        for(const branch of outs){
          if(!Array.isArray(branch))continue;
          for(const edge of branch){
            if(!edge||typeof edge.node!=='string'||!nameSet.has(edge.node))issues.push('connection target missing: '+String(edge&&edge.node));
          }
        }
      }
    }
  }
}

const ok=!!(w&&issues.length===0&&x.ai_valid);
return [{json:{...x,_wf:w,_structural_issues:issues,_structural_valid:ok}}];

const x=$input.first().json;
const status=x._final_status||'failed';
const data=x.ai_data||{};
const wf=x._wf||null;
const nodeCount=wf&&Array.isArray(wf.nodes)?wf.nodes.filter(n=>n&&typeof n==='object').length:0;
let connCount=0;
if(wf&&wf.connections&&typeof wf.connections==='object'){for(const g of Object.values(wf.connections)){if(!g||typeof g!=='object')continue;for(const outs of Object.values(g)){if(!Array.isArray(outs))continue;for(const o of outs)if(Array.isArray(o))connCount+=o.length;}}}

// DIRECT FIX: Fallback for request_id
const reqId = $('Validate Request').first()?.json?.request_id || x.request_id || 'fallback-id';

const evidence=[];
if(x.requirements_hash)evidence.push('requirements_hash='+x.requirements_hash);
if(x.target_n8n_version)evidence.push('target_n8n_version='+x.target_n8n_version);
evidence.push('ai_valid='+x.ai_valid+' structural_valid='+(x._structural_valid===true));
const limitations=['Static structural checks only; import and runtime execution have not been tested.','Import success is not claimed until an actual import is verified.','Webhook authentication is required (Header Auth).','user_id/workspace_id/project_id accepted from authenticated caller as-is; ownership verification pending.','Idempotency: repeated request_id returns 409 VERSION_CONFLICT (audit_id unique).'];
if(!x.ai_valid)limitations.push('AI generation unavailable or invalid: '+(x.ai_error||'unknown'));
if(x.target_n8n_version)limitations.push('Target n8n version was supplied but compatibility was NOT fully verified.');
else limitations.push('target_n8n_version not provided; version-specific compatibility not checked.');
limitations.push('Memory prefetched from WF-07 tables (project, skill) but not verified for freshness.');
if(x.blueprint_reference)limitations.push('blueprint_reference passed as string identifier only; authoritative blueprint retrieval not implemented.');
limitations.push(...(data.limitations||[]));
const providerUsed=x.ai_valid?(x.ai_provider||'groq'):'none';
const modelUsed=providerUsed==='gemini'?'gemini-2.0-flash':(providerUsed==='groq'?'openai/gpt-oss-120b':'none');
const verificationSummary={status:'not_verified',evidence,compatibility_status:x._compatibility_status||'not_checked',provider:providerUsed,model:modelUsed};
const recommendedFixes=(x._all_issues||[]).map((iss,i)=>({finding_id:'V'+String(i+1).padStart(3,'0'),fix:'Address: '+iss.message}));

const result={
    audit_id:'GEN-'+reqId, 
    audit_status:status,
    generated_workflow_json:wf,
    validation_result:{status:status==='success'?'valid':(x.ai_valid?'invalid':'not_produced'),checks_run:['outer JSON parse','workflow.name string','nodes array','connections object','per-node fields','duplicate ids/names','connection references','no inline credentials','no active:true','no hardcoded secret patterns','reference node-type & version check','n8n version compatibility'],issues:x._all_issues||[],issues_total:(x._all_issues||[]).length,essentials_notes:x._essentials_notes||[]},
    assumptions:data.assumptions||[],
    unresolved_requirements:data.unresolved_requirements||[],
    limitations,
    recommended_fixes:recommendedFixes,
    verification_summary:verificationSummary,
    target_n8n_version:x.target_n8n_version||null,
    blueprint_reference:x.blueprint_reference||null,
    node_count:nodeCount,
    connection_count:connCount
};

const httpStatus=status==='failed'?500:200;
const errors=[];
if(!x.ai_valid&&x.ai_error)errors.push({category:x.ai_error_category||'MODEL_ERROR',message:'AI generation unavailable: '+x.ai_error});
if(x.ai_valid&&!x._structural_valid)errors.push({category:'VALIDATION_FAILED',message:'Generated workflow failed structural checks',details:(x._all_issues||[]).slice(0,10).map(i=>i.message)});

const warnings=status==='partial'?[{message:'Generation incomplete or validation issues present'}]:[];

return [{json:{
    request_id:reqId, 
    task_id:null, 
    status:status==='success'?'completed':(status==='partial'?'partial':'failed'), 
    _http_status:httpStatus, 
    result, 
    errors, 
    warnings, 
    verification:verificationSummary, 
    _persist:{
        project_id:x.project_id, 
        user_id:x.user_id, 
        claimed_user_id:x.user_id, 
        workspace_id:x.workspace_id, 
        conversation_id:x.conversation_id, 
        node_count:nodeCount
    }
}}];
